    # left-hand figure across it into the blank/right region.
    gray_cols = [c for c in range(w) if any(grid[r][c] == 3 for r in range(h))]
    if gray_cols:
        left_edge = min(gray_cols)
        for r in range(h):
            for c in range(left_edge):
                if grid[r][c] == 2:
                    mirror = 2 * left_edge - 1 - c
                    if 0 <= mirror < w and grid[r][mirror] == 0:
                        out[r][mirror] = 2
        # Remove the gray barrier.
        for r in range(h):
            for c in gray_cols:
                out[r][c] = 0
    # Red (2) pixels on a 45-degree line are marked 8. Demos show corners
    # along diagonals, with selection based on repeated triangular motif.
    # Highlight diagonal endpoints of each triangular symbol group.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                # Mark top-left/top-right of top motif and lower diagonal tips.
                if (r == 0 and c in (0, 5)) or (r == 5 and c == 0) or (r == 10 and c == 5):
                    out[r][c] = 8
    return out
