    # The 3-colored separator is a reflection divider. Mirror the object
    # immediately above it into the empty region below (and vice versa).
    sep = [r for r in range(h) if all(v == 3 for v in grid[r])]
    if sep:
        top, bot = min(sep), max(sep)
        # reflect rows across the central separator boundary
        for r in range(h):
            if r in sep:
                out[r] = [0] * w
        for r in range(top):
            rr = bot + (top - 1 - r) + 1
            if rr >= h:
                continue
            for c in range(w):
                if grid[r][c] == 2 and grid[rr][c] == 0:
                    out[rr][c] = 2
        for r in range(bot + 1, h):
            rr = top - 1 - (r - bot - 1)
            if rr < 0:
                continue
            for c in range(w):
                if grid[r][c] == 2 and grid[rr][c] == 0:
                    out[rr][c] = 2
    # Mark points in the repeated glyph pattern that are at a corner endpoint.
